use crate::aap::caps::inference_llm::infer;
use crate::aap::caps::types::{
    EscalationRequest, ModeratedQuery, ModerationResult, PolicyViolation,
};

struct Node;

impl Guest for Node {
    fn run(query: CustomerQuery) -> ModerationResult {
        if query.question.len() > 512 {
            return ModerationResult::Violation(PolicyViolation {
                reason: "question exceeds maximum length".to_string(),
            });
        }

        let system = "You are a content moderation assistant. \
            Respond with VIOLATION if the input violates policy, \
            ESCALATE if it needs human review, or OK otherwise."
            .to_string();
        let prompt = query.question.clone();
        let task = "moderate".to_string();

        let verdict = infer(&system, &prompt, &task);
        let verdict_upper = verdict.to_uppercase();

        if verdict_upper.contains("VIOLATION") {
            ModerationResult::Violation(PolicyViolation {
                reason: "content flagged by moderation model".to_string(),
            })
        } else if verdict_upper.contains("ESCALATE") {
            ModerationResult::Escalation(EscalationRequest {
                query,
                reason: "flagged for human review by moderation model".to_string(),
            })
        } else {
            ModerationResult::Ok(ModeratedQuery { query })
        }
    }
}

export!(Node);
```

